#ifndef MULTIAPP_APPS_H_
#define MULTIAPP_APPS_H_

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

/* An extension built with this image (embedded.c, generated by CMakeLists.txt). */
struct multiapp_embedded {
	const char *name;
	/* Its file (the ELF and its trailer), NULL without CONFIG_MULTIAPP_EMBEDDED. */
	const uint8_t *elf;
	size_t size;
	/* MULTIAPP_USB_*: the USB classes it needs. */
	uint32_t usb;
	/* Whether it has buffers in multiapp_area, which it then owns for the boot. */
	bool area;
};

extern const struct multiapp_embedded multiapp_embedded[];
extern const size_t multiapp_embedded_count;

const struct multiapp_embedded *multiapp_embedded_find(const char *name);

/* Load @p name and start its main(); -EBUSY once an app is loaded. */
int multiapp_start(const char *name);

/*
 * Start @p name now, or (returns 1) reboot into it: when an app is loaded or
 * USB runs another profile.
 */
int multiapp_request(const char *name);

/* At boot: start the app a request or CONFIG_MULTIAPP_AUTOSTART names; true if one runs. */
bool multiapp_boot(void);

/* A global function of the loaded app, by name (its hooks), or NULL. */
void *multiapp_app_fn(const char *name);

/* What an app's app_usb_init() calls: nothing to do (include/multiapp/ext.h). */
int multiapp_ext_usb_init(void);

/* Measure main()'s stack use as it returns, for "app info". */
void multiapp_note_main_stack(void);

/*
 * The apps as files on the FAT volume (drive.c). Only at boot, before USB
 * starts and before an app runs (its buffers are in bank 0).
 */
/* Mount, look up and check every built-in app's file, unmount; 0 or -errno (no volume). */
int multiapp_drive_scan(void);
/* The scan's result: 0, or why there is no volume. */
int multiapp_drive_status(void);
/* What the scan found for @p name: its size (or -errno) and whether it equals the built-in one. */
int multiapp_drive_file(const char *name, ssize_t *size, bool *same);
/* Hand the volume to the PC over USB (a boot without an app): ready the disk. */
int multiapp_drive_export(void);
/* Read @p name's file into @p buf: its size, or -errno. */
ssize_t multiapp_drive_read(const char *name, uint8_t *buf, size_t max);

#endif /* MULTIAPP_APPS_H_ */
